scriptCode:
// --- DOMAIN ---
// Declared here, not only in the JSON: without these directives the limit fields
// arrived as 0/0 and updateULimits() discarded the impossible range, leaving in the
// engine the one of the preset loaded BEFORE -- if narrow, the knot looked cut.
u_min := 0;
u_max := 6.28318;   // 2*PI: one full turn of the parameter, the knot closes up
v_min := 0;
v_max := 6.28318;   // sezione circolare del tubo

// TORUS KNOT (p,q) = (3,4), thickened into a tube.
// The center curve lies on the torus with radii R = 1 and r = B: it makes p turns
// around the axis and q turns around the tube before closing up. p and q are
// coprime, so it is ONE single closed loop, and with both > 1 it is a true knot.
//
// A = radius of the tube. The curve comes as close as 0.307 to itself, so
// beyond A = 0.153 the branches interpenetrate.
// B = radius r of the supporting torus.
//
// FRAME FROM THE TORUS, NOT FRENET.
// The Frenet frame rotates abruptly around the curve where the curvature
// is minimal: on this knot the normal jumped by 25 degrees at u = pi/4, 3pi/4,
// 5pi/4, 7pi/4 (the curvature minima, 0.0439), and the tube showed four
// PINCHES there -- sudden twists of the cross-section, not geometric defects.
// Here the normal is taken instead from the SURFACE OF THE TORUS the curve
// lives on: it is defined everywhere, does not depend on the second derivative
// and has nothing to jump from. Maximum jump measured: 0.9 degrees against 24.74.

float pw = 3.0;          // giri attorno all'asse
float qw = 4.0;          // giri attorno al tubo
float R  = 1.0;
float rr = B;            // radius of the supporting torus

float ang = pw * u;      // posizione angolare attorno all'asse
float rad = R + rr * cos(qw * u);

// Punto sulla curva
vec3 P0 = vec3(rad * cos(ang), rad * sin(ang), rr * sin(qw * u));

// Tangente analitica (derivata esatta, niente differenze finite)
vec3 T = vec3(
    -rr * qw * sin(qw * u) * cos(ang) - rad * pw * sin(ang),
    -rr * qw * sin(qw * u) * sin(ang) + rad * pw * cos(ang),
     rr * qw * cos(qw * u));
T = normalize(T);

// Normal of the torus surface at the point: from the center of the tube toward P0.
// The center of the tube is the point of the guide circle at the same angular
// position, at distance R from the axis.
vec3 axis   = vec3(cos(ang), sin(ang), 0.0);
vec3 center = R * axis;
vec3 Nn     = normalize(P0 - center);

// Orthogonalize against the tangent (Gram-Schmidt) and complete the frame
Nn = normalize(Nn - dot(Nn, T) * T);
vec3 Bn = cross(T, Nn);

// Circular cross-section of radius A in the normal plane
return vec4(P0 + A * (cos(v) * Nn + sin(v) * Bn), 0.0);
